namespace Modular.Modules.FederationManagement.Application;
public sealed class FederationManagementStore { internal readonly List<AthleteDto> Athletes=[]; internal readonly List<ClubDto> Clubs=[]; internal readonly List<TournamentDto> Tournaments=[]; internal readonly List<MatchDto> Matches=[]; internal readonly object Gate=new(); }
public sealed class FederationManagementService(FederationManagementStore s,FederationManagementValidator v) { public IReadOnlyList<AthleteDto> GetAthletes(){lock(s.Gate)return s.Athletes.ToArray();} public IReadOnlyList<ClubDto> GetClubs(){lock(s.Gate)return s.Clubs.ToArray();} public AthleteDto? GetAthlete(Guid id){lock(s.Gate)return s.Athletes.FirstOrDefault(x=>x.Id==id);} public ClubDto CreateClub(CreateClubRequest r){if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.City)||string.IsNullOrWhiteSpace(r.RegistrationCode))throw new ArgumentException("مشخصات باشگاه الزامی است.");lock(s.Gate){var c=new ClubDto(Guid.NewGuid(),r.Name.Trim(),r.City.Trim(),r.RegistrationCode.Trim());s.Clubs.Add(c);return c;}} public AthleteDto RegisterAthlete(RegisterAthleteRequest r){var e=v.Validate(r);if(e.Count>0)throw new ArgumentException(string.Join(" ",e));lock(s.Gate){var c=s.Clubs.FirstOrDefault(x=>x.Id==r.ClubId)??throw new KeyNotFoundException();if(s.Athletes.Any(x=>x.NationalId==r.NationalId))throw new InvalidOperationException("شناسه ملی تکراری است.");var a=new AthleteDto(Guid.NewGuid(),r.FullName.Trim(),r.BirthDate,r.NationalId.Trim(),c.Id,c.Name,r.Belt,r.Rank,true);s.Athletes.Add(a);return a;}} public IReadOnlyList<TournamentDto> GetTournaments(){lock(s.Gate)return s.Tournaments.ToArray();} public TournamentDto CreateTournament(CreateTournamentRequest r){var e=v.Validate(r);if(e.Count>0)throw new ArgumentException(string.Join(" ",e));lock(s.Gate){var t=new TournamentDto(Guid.NewGuid(),r.Name,r.StartDate,r.Venue,"Planned",s.Athletes.Count);s.Tournaments.Add(t);return t;}} public IReadOnlyList<MatchDto> PairTournament(Guid id){lock(s.Gate){var t=s.Tournaments.FirstOrDefault(x=>x.Id==id)??throw new KeyNotFoundException();var a=s.Athletes.Where(x=>x.IsActive).OrderBy(x=>x.Belt).ThenBy(x=>x.Rank).ToArray();var ms=new List<MatchDto>();for(int i=0;i+1<a.Length;i+=2){var m=new MatchDto(Guid.NewGuid(),id,a[i].Id,a[i+1].Id,null,null,null);s.Matches.Add(m);ms.Add(m);}var ti=s.Tournaments.FindIndex(x=>x.Id==id);s.Tournaments[ti]=t with {Status="Paired",AthleteCount=a.Length};return ms;}} public MatchDto RecordResult(Guid id,int red,int blue){if(red<0||blue<0||red==blue)throw new ArgumentException("نتیجه باید نامساوی و غیرمنفی باشد.");lock(s.Gate){var i=s.Matches.FindIndex(x=>x.Id==id);if(i<0)throw new KeyNotFoundException();var m=s.Matches[i] with {RedScore=red,BlueScore=blue,WinnerId=red>blue?s.Matches[i].RedAthleteId:s.Matches[i].BlueAthleteId};s.Matches[i]=m;return m;}} public IReadOnlyList<RankingDto> GetRankings(){lock(s.Gate)return s.Athletes.Select(a=>{var ms=s.Matches.Where(m=>m.WinnerId.HasValue&&(m.RedAthleteId==a.Id||m.BlueAthleteId==a.Id));int w=ms.Count(m=>m.WinnerId==a.Id),l=ms.Count()-w;return new RankingDto(a.Id,a.FullName,a.ClubName,a.Belt,CalculateGrade(a.Rank,w,l),w,l,w*3);}).OrderByDescending(x=>x.Points).ToArray();} public static int CalculateGrade(int rank,int wins,int losses)=>Math.Clamp(rank+wins-losses,1,10); }
